<?php
namespace App\Services;
use PDO;use Illuminate\Support\Str;
final class GalleryStore {
 public readonly PDO $db;
 public function __construct(string $path){if(!is_file($path))throw new \RuntimeException('Initialize the gallery database first');$this->db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$this->db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');if((int)$this->db->query('PRAGMA user_version')->fetchColumn()!==4)throw new \RuntimeException('Gallery schema 4 required; run gallery:migrate');}
 public function transaction(callable $fn):mixed {$this->db->exec('BEGIN IMMEDIATE');try{$r=$fn();$this->db->exec('COMMIT');return $r;}catch(\Throwable $e){$this->db->exec('ROLLBACK');throw $e;}}
 public function run(string $sql,array $args=[]):\PDOStatement {$q=$this->db->prepare($sql);$q->execute($args);return $q;}
 public function ingest(string $bytes,string $artist,string $title,array $tags=[],string $description="",?string $requestId=null):array {
  if(!preg_match('/^[a-z0-9-]{1,64}$/D',$artist)||!trim($title)||mb_strlen(trim($title))>120||preg_match('/[\x00-\x1f\x7f]/',$title)||count($tags)>8)throw new \InvalidArgumentException('Invalid metadata');foreach($tags as $tag)if(!is_string($tag)||!preg_match('/^[a-z0-9-]{1,32}$/D',$tag))throw new \InvalidArgumentException('Invalid tag');
  if(!$this->run('SELECT id FROM artists WHERE id=?',[$artist])->fetch())throw new \InvalidArgumentException('Artist does not exist');$a=Png::prepare($bytes);if(strlen($a['image'])>1048576)throw new \InvalidArgumentException('Canonical image exceeds 1 MiB');$id=(string)Str::uuid();
  $result=$this->transaction(function()use($a,$id,$artist,$title,$tags,$description,$requestId){if($requestId){$existing=$this->run("SELECT artwork FROM artwork_details WHERE request_id=?",[$requestId])->fetchColumn();if($existing)return $existing;}abort_if((int)$this->run("SELECT count(*) FROM artworks WHERE artist=? AND status IN ('pending','held')",[$artist])->fetchColumn()>=20,429,"Review queue full: wait for your pending artwork to be reviewed.");$q=$this->db->prepare('INSERT INTO artworks VALUES (?,?,?,?,?,?,?,?,?,?,?)');$args=[$id,$artist,trim($title),json_encode(array_values(array_unique($tags))),$a['width'],$a['height'],'pending','private','',0,$a['image']];foreach($args as $i=>$value)$q->bindValue($i+1,$value,$i===10?PDO::PARAM_LOB:(is_int($value)?PDO::PARAM_INT:PDO::PARAM_STR));$q->execute();$q=$this->db->prepare('INSERT INTO derivatives VALUES (?,?,?,?)');$q->bindValue(1,$id);$q->bindValue(2,$a['thumbnailWidth'],PDO::PARAM_INT);$q->bindValue(3,$a['thumbnailHeight'],PDO::PARAM_INT);$q->bindValue(4,$a['thumbnail'],PDO::PARAM_LOB);$q->execute();$this->run('INSERT INTO moderation_queue(artwork) VALUES (?)',[$id]);$this->run('INSERT INTO artwork_details VALUES (?,?,?,?)',[$id,$description,(int)floor(microtime(true)*1000),$requestId]);return $id;});return ['id'=>$result,'width'=>$a['width'],'height'=>$a['height'],'status'=>'pending','visibility'=>'private'];
 }
}
